parameters.text:
=Evaluate this lead application for the AI Workflow Implementation Package.

Use the submitted lead data below to decide whether the lead is:
- qualified
- not_qualified
- human_review

Qualification guidance:
- The business should be actively operating or clearly preparing to launch.
- The lead should describe a real business process or operational problem that could plausibly benefit from automation.
- Stronger fit generally means the problem happens repeatedly and has a meaningful business impact.
- The current offer starts at $3,000, so budget should be considered seriously.
- The lead should have meaningful involvement in approving the investment.
- A timeline within 90 days is generally a stronger fit.
- Use human_review when the application is ambiguous, contradictory, incomplete, or presents an edge case that should not be automatically accepted or rejected.
- Do not invent facts that are not present in the application.

After evaluating the lead:

1. Use the HighLevel contact tool to create or update the lead as a contact using the submitted name, email, and business name.
2. Capture the exact contact ID returned by the HighLevel contact tool.
3. Use that returned contact ID to call the HighLevel qualification tag tool.
4. Add exactly one qualification-status tag based on your decision:
   - qualified → "qualified"
   - human_review → "human-review"
   - not_qualified → "not-qualified"
5. Do not remove or replace any existing HighLevel tags.
6. Do not invent contact information or a contact ID.
7. Return the exact HighLevel contact ID from the contact upsert tool in the highlevel_contact_id field of the structured output.

Return only the structured output required by the connected output parser.

Lead data:
Name: {{ $json.input.name }}
Email: {{ $json.input.email }}
Business name: {{ $json.input.business_name }}
Business type: {{ $json.input.business_type }}
Operating status: {{ $json.input.operating_status }}
Problem: {{ $json.input.problem }}
Frequency: {{ $json.input.frequency }}
Business impact: {{ $json.input.business_impact }}
Desired outcome: {{ $json.input.desired_outcome }}
Budget: {{ $json.input.budget }}
Decision authority: {{ $json.input.decision_authority }}
Timeline: {{ $json.input.timeline }}
Additional notes: {{ $json.input.additional_notes }}

parameters.jsCode:
const { name, email, business_name } = query;

const contactId = `SIM-${email.replace(/[^a-zA-Z0-9]/g, "").toUpperCase()}`;

return JSON.stringify({
  contact_id: contactId,
  name,
  email,
  business_name
});

const { contact_id, tag } = query;

return JSON.stringify({
  contact_id,
  tag,
  applied: true
});

const actual = $json.output ?? {};
const acceptable = $json.acceptable_decisions ?? [];

const validDecisions = [
  "qualified",
  "not_qualified",
  "human_review"
];

const decisionPass = acceptable.includes(actual.decision);

const schemaPass =
  validDecisions.includes(actual.decision) &&
  typeof actual.reason === "string" &&
  actual.reason.trim().length > 0 &&
  typeof actual.confidence === "number" &&
  actual.confidence >= 0 &&
  actual.confidence <= 1 &&
  typeof actual.recommended_next_action === "string" &&
  actual.recommended_next_action.trim().length > 0 &&
  typeof actual.highlevel_contact_id === "string" &&
  actual.highlevel_contact_id.trim().length > 0;

const steps = $json.intermediateSteps ?? [];

function getToolResponse(toolName) {
  const step = steps.find(s => s.action?.tool === toolName);
  if (!step) return null;

  try {
    return JSON.parse(JSON.parse(step.observation)[0].response);
  } catch {
    return null;
  }
}

const contactResponse = getToolResponse(
  "Simulated_HighLevel_Contact"
);

const contactPass =
  contactResponse !== null &&
  contactResponse.contact_id === actual.highlevel_contact_id &&
  contactResponse.name === $json.input.name &&
  contactResponse.email === $json.input.email &&
  contactResponse.business_name === $json.input.business_name;

const tagResponse = getToolResponse(
  "Simulated_HighLevel_Qualification_Tag"
);

const expectedTag = {
  qualified: "qualified",
  not_qualified: "not-qualified",
  human_review: "human-review"
}[actual.decision];

const tagPass =
  tagResponse !== null &&
  tagResponse.applied === true &&
  tagResponse.tag === expectedTag &&
  tagResponse.contact_id === actual.highlevel_contact_id;

return {
  json: {
    case_id: $json.case_id,
    category: $json.category,
    expected_decisions: acceptable,
    actual_decision: actual.decision ?? null,
    decision_pass: decisionPass,
    schema_pass: schemaPass,
    contact_pass: contactPass,
    tag_pass: tagPass,
    confidence: actual.confidence ?? null,
    reason: actual.reason ?? null,
    recommended_next_action: actual.recommended_next_action ?? null,
    highlevel_contact_id: actual.highlevel_contact_id ?? null,
    overall_pass: decisionPass && schemaPass && contactPass && tagPass
  }
};
